 s=str(x).strip().lower().replace(' ','_').replace('/','_')
 mp={'root_cap':'root_cap','epidermis':'epidermis','cortex':'cortex','endodermis':'endodermis','pericycle':'pericycle','xylem':'xylem','phloem':'phloem','provascular':'provascular','g1_s':'meristems','g2_m':'meristems'}
 return mp.get(s,s)
def extract_ids(v):
 if v is None: return []
 return re.findall(r'TraesCS[A-Za-z0-9]+(?:LC)?',str(v))
refs={}
# Conserved cross-species marker ranking
ws=wb('mmc10.xlsx')['T. aestivum']; it=ws.iter_rows(values_only=True); h=list(next(it)); ix={str(v):i for i,v in enumerate(h)}
for r in it:
 try: t=norm(r[ix['Cell type']]); rank=float(r[ix['Rank']]); present=bool(r[ix['T. aestivum']])
 except Exception: continue
 if t in labs and present and rank<=500:
  refs.setdefault('conserved',{}).setdefault(t,[]).extend(extract_ids(r[ix['Best marker']])+extract_ids(r[ix['Other markers']]))
